SELECT s.city, CASE WHEN s.rating >= 3.8 THEN 'high' WHEN s.rating >= 2.0 THEN 'mid' ELSE 'low' END AS rating_bucket, COUNT(CASE WHEN p.category = 'Sports' THEN 1 END) AS sports_count, MIN(p.launch_date) AS first_launch_date FROM products p LEFT JOIN suppliers s ON p.supplier_id = s.id GROUP BY s.city, CASE WHEN s.rating >= 3.8 THEN 'high' WHEN s.rating >= 2.0 THEN 'mid' ELSE 'low' END
